// Generated by Cypress Author on 2026-10-22
//
// USU 03 · USU 05 · USU 06 · USU 07 (UI) — Plano_de_Testes_QA_MatchWallet.md §4 (docs-test/areas/usu.md).
// O sistema não tem "Novo usuário" pelo admin (não existe `POST /usuarios`): o único cadastro é o
// auto-cadastro em `/criar-conta`, sempre como Cliente. Os casos de formulário valem para esse
// formulário; o servidor é testado em `real/usuarios-servidor`.
//
// ATENÇÃO — "USU 06 · nome só com espaços" deve FALHAR: o schema usa `min(1)` sem `trim()`.

const CONTA = { nome: 'Maria da Silva', email: 'maria.nova@teste.com', senha: 'Senha@12345' }

function stubCadastro(atrasoRegistro = 0) {
  cy.bloquearApi()
  cy.stubLogin({ email: CONTA.email, senha: CONTA.senha })
  cy.stubApi(
    'GET',
    '/suitability/perguntas',
    [{ id: 'p1', enunciado: 'Pergunta 1', opcoes: [{ id: 'o1', texto: 'Opção', peso: 1 }] }],
    'perguntas',
  )
  cy.intercept('POST', '**/api/v1/auth/register', (req) => {
    req.reply({
      statusCode: 201,
      delay: atrasoRegistro,
      body: {
        id: 'novo-1',
        nome: req.body.nome,
        email: req.body.email,
        perfil: 'cliente',
        ativo: true,
      },
    })
  }).as('registrar')
}

function preencher(campos: Partial<typeof CONTA>) {
  const alvo = {
    nome: 'input[autocomplete="name"]',
    email: 'input[type="email"]',
    senha: 'input[type="password"]',
  } as const
  for (const [campo, valor] of Object.entries(campos)) {
    const seletor = alvo[campo as keyof typeof alvo]
    cy.get(seletor).clear()
    if (valor) cy.get(seletor).type(valor, { parseSpecialCharSequences: false })
  }
}

function enviar() {
  cy.contains('button', /Criar conta|Criando conta/).click()
}

describe('Plano QA · Cadastro de usuário (UI) — USU 03, 05, 06, 07', () => {
  beforeEach(() => {
    stubCadastro()
    cy.visit('/criar-conta')
  })

  it('USU 03 · cadastro válido → envia nome, e-mail e senha (sem papel), entra e segue para a avaliação', () => {
    preencher(CONTA)
    enviar()

    // O papel nunca vem do navegador: só `nome`, `email` e `senha`.
    cy.wait('@registrar').its('request.body').should('deep.equal', CONTA)
    cy.wait('@login')
    cy.location('pathname').should('eq', '/avaliacao-perfil')
    cy.get('@registrar.all').should('have.length', 1)
  })

  it('USU 05 · senha com 7 caracteres, sem número, sem símbolo e válida → só a válida é enviada, sem repetir a senha na tela', () => {
    preencher({ nome: CONTA.nome, email: CONTA.email })

    const regras = [
      { senha: 'Ab1!xyz', mensagem: 'A senha precisa ter no mínimo 8 caracteres' },
      { senha: 'Abcdefg!', mensagem: 'A senha precisa de ao menos 1 número' },
      { senha: 'Abcdefg1', mensagem: 'A senha precisa de ao menos 1 caractere especial' },
    ]
    for (const { senha, mensagem } of regras) {
      preencher({ senha })
      enviar()
      cy.contains(mensagem).should('be.visible')
      // A mensagem descreve a regra; nunca ecoa a senha digitada.
      cy.get('[data-slot="form-message"], [id$="-form-item-message"]').each(($m) => {
        expect($m.text()).not.to.contain(senha)
      })
    }
    cy.get('@registrar.all').should('have.length', 0)
    cy.get('input[type="password"]').should('have.attr', 'type', 'password')

    preencher({ senha: 'Abcdef1!' })
    enviar()
    cy.wait('@registrar').its('request.body.senha').should('eq', 'Abcdef1!')
  })

  it('USU 06 · campos vazios, e-mail malformado e e-mail duplicado (409) → mensagens claras e nenhum cadastro parcial', () => {
    // Tudo vazio.
    enviar()
    cy.contains('Informe seu nome completo').should('be.visible')
    cy.contains('Informe seu e-mail').should('be.visible')
    cy.contains('Informe uma senha').should('be.visible')

    // E-mail aceito pelo navegador, recusado pelo schema.
    preencher({ nome: CONTA.nome, email: 'maria@teste', senha: CONTA.senha })
    enviar()
    cy.contains('Informe um e-mail válido').should('be.visible')

    // E-mail sem "@": barrado pela validação nativa antes do submit.
    preencher({ email: 'sem-arroba' })
    enviar()
    cy.get('input[type="email"]').then(($e) => {
      expect(($e[0] as HTMLInputElement).validity.valid).to.eq(false)
    })
    cy.get('@registrar.all').should('have.length', 0)

    // Duplicado: o servidor recusa e a tela mostra o motivo, sem ir adiante.
    cy.intercept('POST', '**/api/v1/auth/register', {
      statusCode: 409,
      body: { error: { code: 'CONFLICT', message: 'E-mail já cadastrado.' } },
    }).as('registrarDuplicado')
    preencher({ email: CONTA.email })
    enviar()
    cy.wait('@registrarDuplicado')
    cy.get('[role="alert"]').should('contain.text', 'E-mail já cadastrado.')
    cy.location('pathname').should('eq', '/criar-conta')
    cy.contains('button', 'Criar conta').should('be.enabled')
    cy.get('@login.all').should('have.length', 0)
  })

  it('USU 06 · nome só com espaços → recusado como vazio, sem envio (falha até aparar o nome)', () => {
    preencher({ nome: '     ', email: CONTA.email, senha: CONTA.senha })
    enviar()

    cy.contains('Informe seu nome completo').should('be.visible')
    cy.get('@registrar.all').should('have.length', 0)
  })

  it('USU 07 · "Entrar" e clique duplo em "Criar conta" → sair não grava e o envio duplo gera um só cadastro', () => {
    // Sair pela ligação "Entrar" com o formulário preenchido: nada é enviado.
    preencher(CONTA)
    cy.contains('a', 'Entrar').click()
    cy.location('pathname').should('eq', '/login')
    cy.get('@registrar.all').should('have.length', 0)

    // Reabre e envia com clique duplo, com o POST ainda em voo.
    stubCadastro(400)
    cy.visit('/criar-conta')
    preencher(CONTA)
    cy.contains('button', 'Criar conta').dblclick()
    cy.location('pathname', { timeout: 10000 }).should('eq', '/avaliacao-perfil')
    cy.get('@registrar.all').should('have.length', 1)
    cy.get('@login.all').should('have.length', 1)
  })

  it('USU 07 · timeout no cadastro e nova tentativa → erro sem falso sucesso, dados mantidos e um único cadastro ao final', () => {
    let chamadas = 0
    cy.intercept('POST', '**/api/v1/auth/register', (req) => {
      chamadas += 1
      if (chamadas === 1) {
        req.reply({
          statusCode: 504,
          body: {
            error: { code: 'GATEWAY_TIMEOUT', message: 'O servidor demorou para responder.' },
          },
        })
        return
      }
      req.reply({
        statusCode: 201,
        body: {
          id: 'novo-1',
          nome: req.body.nome,
          email: req.body.email,
          perfil: 'cliente',
          ativo: true,
        },
      })
    }).as('registrarTimeout')

    preencher(CONTA)
    enviar()
    cy.wait('@registrarTimeout')
    cy.get('[role="alert"]').should('contain.text', 'O servidor demorou para responder.')
    cy.location('pathname').should('eq', '/criar-conta')
    cy.get('input[type="email"]').should('have.value', CONTA.email)
    cy.contains('button', 'Criar conta').should('be.enabled')
    cy.get('@login.all').should('have.length', 0)

    enviar()
    cy.location('pathname').should('eq', '/avaliacao-perfil')
    cy.get('@registrarTimeout.all').should('have.length', 2)
  })
})

export {}
